INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1600, 'identify', '/aɪˈdentɪfaɪ/', 'verb', '{"zh-TW":["識別；辨認","確認"],"en":["to establish the identity of","to recognize or establish the identity of","to determine"]}', '{"root":{"text":"ident","meaning":"same (相同)"},"suffix":{"text":"-ify","meaning":"make (使)"},"logic":"使確認為同一個，即「識別」。"}', 'identify a problem / identify with / identify the cause; identify a problem/need/trend', '[{"en":"Can you identify the person in this photo?","zh-TW":"你能認出照片中的人嗎？"},{"en":"We need to identify the root cause.","zh-TW":"我們需要找出根本原因。"},{"en":"The police identified the suspect from CCTV footage.","zh-TW":"警方從監控錄像中辨認出了嫌疑人。"},{"en":"We need to identify the root cause of the issue.","zh-TW":"我們需要找出問題的根本原因。"}]', '{"noun":"identification","noun2":"identity","adjective":"identifiable","verb":"identify"}', NULL, 3, 1600, 132),
(1601, 'ignore', '/ɪɡˈnɔːr/', 'verb', '{"zh-TW":["忽視；不理睬"],"en":["to refuse to take notice of"]}', NULL, 'ignore advice/warnings/rules', '[{"en":"You should not ignore the safety warnings.","zh-TW":"你不應該忽視安全警告。"},{"en":"He chose to ignore her complaints.","zh-TW":"他選擇忽視她的投訴。"}]', '{"noun":"ignorance","verb":"ignore","adjective":"ignorant"}', NULL, 2, 1601, NULL),
(1602, 'illustrate', '/ˈɪləstreɪt/', 'verb', '{"zh-TW":["說明；描繪","說明；闡釋","為...加插圖"],"en":["to explain or make clear by using examples or pictures","to explain by examples","to provide pictures for a book"]}', '{"prefix":{"text":"il-","meaning":"in (在內)"},"root":{"text":"lustr","meaning":"light (光)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使光照入使其清楚，即「說明」。"}', 'illustrate a point / clearly illustrate; illustrate a point/concept', '[{"en":"The graph illustrates the trend clearly.","zh-TW":"圖表清楚地說明了趨勢。"},{"en":"Let me illustrate with an example.","zh-TW":"讓我用一個例子來說明。"},{"en":"The chart illustrates the trend in sales.","zh-TW":"這張圖表說明了銷售趨勢。"},{"en":"Let me illustrate my point with an example.","zh-TW":"讓我用一個例子來說明我的觀點。"}]', '{"noun":"illustration","noun2":"illustrator","verb":"illustrate","adjective":"illustrative"}', NULL, 4, 1602, NULL),
(1603, 'image', '/ˈɪmɪdʒ/', 'noun', '{"zh-TW":["形象；圖像"],"en":["the impression people have of a person or company; a picture"]}', NULL, 'brand/public/corporate image', '[{"en":"The company is trying to improve its public image.","zh-TW":"公司正在努力改善其公眾形象。"},{"en":"Digital images can be edited easily.","zh-TW":"數位圖像可以輕鬆編輯。"}]', '{"noun":"image, imagery","verb":"imagine","adjective":"imaginary"}', NULL, 2, 1603, NULL),
(1604, 'imagine', '/ɪˈmædʒɪn/', 'verb', '{"zh-TW":["想像"],"en":["to form a mental picture of something"]}', NULL, 'hard to imagine / imagine that', '[{"en":"Imagine how the customer feels.","zh-TW":"想像客戶的感受。"},{"en":"It is hard to imagine life without technology.","zh-TW":"很難想像沒有科技的生活。"}]', '{"verb":"imagine","noun":"imagination","adjective":"imaginative","adjective2":"imaginary"}', NULL, 3, 1604, NULL),
(1605, 'immediate', '/ɪˈmiːdiət/', 'adjective', '{"zh-TW":["立即的；即時的","直接的"],"en":["happening without delay","nearest in time or relationship"]}', NULL, 'immediate action/response/effect', '[{"en":"We need to take immediate action on this matter.","zh-TW":"我們需要對此事立即採取行動。"},{"en":"The immediate effect was a rise in stock prices.","zh-TW":"直接效果是股價上漲。"}]', '{"noun":"immediacy","adjective":"immediate","adverb":"immediately"}', NULL, 3, 1605, 133),
(1606, 'immense', '/ɪˈmens/', 'adjective', '{"zh-TW":["巨大的；龐大的"],"en":["extremely large or great"]}', NULL, 'immense pressure/value/potential', '[{"en":"The project requires an immense amount of resources.","zh-TW":"該項目需要大量資源。"},{"en":"She has immense experience in the field.","zh-TW":"她在該領域有豐富的經驗。"}]', '{"noun":"immensity","adjective":"immense","adverb":"immensely"}', NULL, 3, 1606, NULL),
(1607, 'immigration', '/ˌɪmɪˈɡreɪʃən/', 'noun', '{"zh-TW":["移民；入境審查"],"en":["the process of entering a foreign country"]}', NULL, 'immigration officer / pass through immigration', '[{"en":"Please have your passport ready at immigration.","zh-TW":"請在入境審查時備好護照。"},{"en":"The immigration process took over an hour.","zh-TW":"入境審查過程花了一個多小時。"}]', '{"verb":"immigrate","adjective":"immigrant"}', NULL, 4, 1607, NULL),
(1608, 'imminent', '/ˈɪmɪnənt/', 'adjective', '{"zh-TW":["即將發生的；迫在眉睫的"],"en":["about to happen very soon"]}', NULL, 'imminent threat / imminent deadline / imminent layoffs', '[{"en":"An imminent regulatory change forced the company to adapt quickly.","zh-TW":"即將到來的監管變化迫使公司迅速調整。"},{"en":"The imminent product launch required all hands on deck.","zh-TW":"即將到來的產品發佈需要所有人全力以赴。"}]', '{"adverb":"imminently","noun":"imminence"}', NULL, 3, 1608, NULL),
(1609, 'immune', '/ɪˈmjuːn/', 'adjective', '{"zh-TW":["免疫的；不受影響的"],"en":["resistant to; not affected by"]}', NULL, 'immune to / immune system / immune from', '[{"en":"No company is immune to economic downturns.","zh-TW":"沒有公司能免受經濟衰退的影響。"},{"en":"The new policy makes no one immune from accountability.","zh-TW":"新政策使沒有人能免除問責。"}]', '{"noun":"immunity, immunization","adjective":"immune","verb":"immunize"}', NULL, 2, 1609, NULL),
(1610, 'immunization', '/ˌɪmjʊnaɪˈzeɪʃən/', 'noun', '{"zh-TW":["免疫接種；疫苗接種"],"en":["the process of making someone immune to a disease"]}', NULL, 'childhood immunization / immunization schedule', '[{"en":"All children should receive the recommended immunizations.","zh-TW":"所有兒童都應接受建議的免疫接種。"},{"en":"International travel may require additional immunizations.","zh-TW":"國際旅行可能需要額外的免疫接種。"}]', '{"verb":"immunize","noun":"immunity"}', NULL, 4, 1610, NULL),
(1611, 'impact', '/ˈɪmpækt/', 'noun, verb', '{"zh-TW":["影響；衝擊"],"en":["a strong effect or influence"]}', NULL, 'have an impact on / environmental impact', '[{"en":"The new policy will have a significant impact on small businesses.","zh-TW":"新政策將對小企業產生重大影響。"},{"en":"Climate change impacts everyone.","zh-TW":"氣候變遷影響每個人。"}]', '{"noun":"impact","verb":"impact","adjective":"impactful"}', NULL, 2, 1611, 368),
(1612, 'impair', '/ɪmˈper/', 'verb', '{"zh-TW":["損害；削弱"],"en":["to weaken or damage something"]}', NULL, 'impair vision/judgment/performance', '[{"en":"Alcohol can impair your judgment.","zh-TW":"酒精會損害你的判斷力。"},{"en":"Noise pollution can impair hearing over time.","zh-TW":"噪音污染長期下來會損害聽力。"}]', '{"noun":"impairment","verb":"impair","adjective":"impaired"}', NULL, 2, 1612, NULL),
(1613, 'impairment', '/ɪmˈpeərmənt/', 'noun', '{"zh-TW":["減值"],"en":["a reduction in the recoverable value of an asset below its carrying value"]}', NULL, 'goodwill impairment / asset impairment / impairment charge / impairment test', '[{"en":"An impairment charge was triggered by falling property values.","zh-TW":"不動產價值下跌引發了減值費用。"},{"en":"The company performed annual goodwill impairment testing.","zh-TW":"公司每年進行商譽減值測試。"}]', '{"verb":"impair","adjective":"impaired"}', NULL, 4, 1613, NULL),
(1614, 'impatient', '/ɪmˈpeɪʃnt/', 'adjective', '{"zh-TW":["不耐煩的"],"en":["not willing to wait or unable to tolerate delay"]}', '{"prefix":{"text":"im-","meaning":"not (不)"},"root":{"text":"patient","meaning":"enduring (忍耐)"},"logic":"不能忍耐的，即「不耐煩的」。"}', 'grow impatient / impatient with', '[{"en":"He grew impatient waiting for the bus.","zh-TW":"他等公車等得不耐煩了。"},{"en":"Don''t be so impatient with the children.","zh-TW":"對孩子們不要那麼沒耐心。"}]', '{"noun":"impatience","adverb":"impatiently"}', NULL, 3, 1614, NULL),
(1615, 'impeach', '/ɪmˈpiːtʃ/', 'verb', '{"zh-TW":["彈劾"],"en":["to charge a public official with misconduct"]}', NULL, 'impeach a president / impeachment trial', '[{"en":"Congress voted to impeach the president.","zh-TW":"國會投票彈劾總統。"},{"en":"The impeachment process began.","zh-TW":"彈劾程序開始了。"}]', '{"noun":"impeachment"}', NULL, 3, 1615, NULL),
(1616, 'impede', '/ɪmˈpiːd/', 'verb', '{"zh-TW":["妨礙；阻礙"],"en":["to delay or prevent something"]}', NULL, 'impede progress/growth/development', '[{"en":"Bureaucracy can impede the progress of reforms.","zh-TW":"官僚主義會妨礙改革的進展。"},{"en":"The construction work impeded traffic flow.","zh-TW":"施工妨礙了交通流暢。"}]', '{"noun":"impediment","verb":"impede"}', NULL, 2, 1616, NULL),
(1617, 'imperative', '/ɪmˈperətɪv/', 'adjective, noun', '{"zh-TW":["迫切的；必要的","必要的事"],"en":["extremely important and urgent","something vital"]}', NULL, 'it is imperative that / moral imperative', '[{"en":"It is imperative that we act quickly.","zh-TW":"我們迫切需要迅速行動。"},{"en":"Data security is a business imperative.","zh-TW":"數據安全是商業上的當務之急。"}]', '{"noun":"imperative","adjective":"imperative"}', NULL, 4, 1617, NULL),
(1618, 'implement', '/ˈɪmplɪment/', 'verb', '{"zh-TW":["實施；執行","工具；器具"],"en":["to put into effect","to put a plan into action","a tool or instrument"]}', '{"prefix":{"text":"im-","meaning":"in (進入)"},"root":{"text":"ple","meaning":"fill (充滿)"},"suffix":{"text":"-ment","meaning":"result (結果)"},"logic":"充實到行動中，即「實施」。"}', 'implement a plan / implement changes / implement a policy; implement a plan/policy/strategy', '[{"en":"The company will implement the new policy next month.","zh-TW":"公司下個月將實施新政策。"},{"en":"It takes time to implement changes.","zh-TW":"實施變革需要時間。"},{"en":"The government plans to implement new regulations.","zh-TW":"政府計劃實施新的法規。"},{"en":"The changes will be implemented next quarter.","zh-TW":"這些變更將在下個季度實施。"}]', '{"noun":"implementation","verb":"implement"}', NULL, 3, 1618, 33),
(1619, 'implementation', '/ˌɪmplɪmenˈteɪʃən/', 'noun', '{"zh-TW":["實施；執行"],"en":["the process of putting a plan, decision, or system into effect"]}', NULL, 'implementation plan / full implementation / phased implementation / implementation timeline', '[{"en":"The implementation of the new system took six months.","zh-TW":"新系統的實施花了六個月。"},{"en":"A detailed implementation plan was shared with all stakeholders.","zh-TW":"詳細的實施計劃與所有利益相關者分享。"}]', '{"verb":"implement","adjective":"implemented"}', NULL, 5, 1619, 578),
(1620, 'implication', '/ˌɪmplɪˈkeɪʃn/', 'noun', '{"zh-TW":["含義；暗示","影響；後果"],"en":["something suggested without being stated","a possible consequence"]}', NULL, 'have implications for / the implications of', '[{"en":"The findings have serious implications for public health.","zh-TW":"這些發現對公共衛生有嚴重影響。"},{"en":"What are the implications of this decision?","zh-TW":"這個決定有什麼含義？"}]', '{"noun":"implication","verb":"imply, implicate","adjective":"implicit"}', NULL, 4, 1620, NULL),
(1621, 'implicit', '/ɪmˈplɪsɪt/', 'adjective', '{"zh-TW":["含蓄的；隱含的"],"en":["implied though not directly expressed"]}', NULL, 'implicit assumption/understanding/trust', '[{"en":"There was an implicit understanding between the partners.","zh-TW":"合作夥伴之間有一種默契。"},{"en":"The risks are implicit in the contract terms.","zh-TW":"風險隱含在合同條款中。"}]', '{"adjective":"implicit","adverb":"implicitly","noun":"implication"}', NULL, 3, 1621, NULL),
(1622, 'imply', '/ɪmˈplaɪ/', 'verb', '{"zh-TW":["暗示；意味著"],"en":["to suggest without stating directly","to suggest something without saying it directly"]}', '{"prefix":{"text":"im-","meaning":"in (在內)"},"root":{"text":"ply","meaning":"fold (折疊)"},"logic":"把意思折藏在裡面，即「暗示」。"}', 'imply that / strongly imply', '[{"en":"Are you implying that I''m wrong?","zh-TW":"你是在暗示我錯了嗎？"},{"en":"The data implies a connection between the two variables.","zh-TW":"數據暗示兩個變數之間有關聯。"},{"en":"Are you implying that I made a mistake?","zh-TW":"你是在暗示我犯了錯嗎？"},{"en":"The data implies a strong correlation.","zh-TW":"數據暗示了很強的相關性。"}]', '{"noun":"implication","adjective":"implicit","verb":"imply"}', NULL, 2, 1622, NULL),
(1623, 'import', '/ˈɪmpɔːrt/', 'noun, verb', '{"zh-TW":["進口；輸入","進口商品"],"en":["to bring goods from another country","goods brought from abroad"]}', NULL, 'import goods/products / import duties', '[{"en":"The country imports most of its oil.","zh-TW":"該國大部分石油依賴進口。"},{"en":"Import duties have been raised by 5%.","zh-TW":"進口關稅提高了5%。"}]', '{"noun":"import, importation, importer","verb":"import"}', NULL, 2, 1623, NULL),
(1624, 'important', '/ɪmˈpɔːrtənt/', 'adjective', '{"zh-TW":["重要的"],"en":["having great value or significance"]}', NULL, 'most important / important role', '[{"en":"Communication is the most important skill.","zh-TW":"溝通是最重要的技能。"},{"en":"She plays an important role in the project.","zh-TW":"她在專案中扮演重要角色。"}]', '{"adjective":"important","noun":"importance","adverb":"importantly","adjective2":"unimportant"}', NULL, 3, 1624, NULL),
(1625, 'impose', '/ɪmˈpoʊz/', 'verb', '{"zh-TW":["施加；強加","強加；施加","徵收"],"en":["to force something on someone","to establish a tax or fine"]}', '{"prefix":{"text":"im-","meaning":"on (在上)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放在某人身上，即「強加」。"}', 'impose restrictions / impose a fine / impose on; impose restrictions/sanctions/a fine', '[{"en":"The government imposed new taxes on imports.","zh-TW":"政府對進口商品徵收新稅。"},{"en":"I don''t want to impose on your time.","zh-TW":"我不想占用你的時間。"},{"en":"The government imposed new restrictions on imports.","zh-TW":"政府對進口實施了新的限制。"},{"en":"A heavy fine was imposed on the company.","zh-TW":"公司被處以高額罰款。"}]', '{"noun":"imposition","verb":"impose"}', NULL, 2, 1625, NULL),
(1626, 'impress', '/ɪmˈpres/', 'verb', '{"zh-TW":["使印象深刻；使欽佩"],"en":["to make someone feel admiration"]}', NULL, 'impress someone with / be impressed by', '[{"en":"Her presentation impressed the entire board.","zh-TW":"她的報告讓整個董事會印象深刻。"},{"en":"I was very impressed by the quality of the work.","zh-TW":"我對工作的品質印象非常深刻。"}]', '{"noun":"impression","verb":"impress","adjective":"impressive, impressed"}', NULL, 3, 1626, NULL),
(1627, 'impression', '/ɪmˈpreʃən/', 'noun', '{"zh-TW":["曝光次數；印象"],"en":["the number of times an advertisement is displayed to users"]}', NULL, 'ad impression / impression rate / cost per thousand impressions', '[{"en":"The campaign generated 5 million impressions in the first week.","zh-TW":"該活動在第一週產生了500萬次曝光。"},{"en":"Impressions measure how often your content is shown, not clicked.","zh-TW":"曝光次數衡量您的內容顯示頻率，而非點擊頻率。"}]', NULL, NULL, 4, 1627, NULL),
(1628, 'improve', '/ɪmˈpruːv/', 'verb', '{"zh-TW":["改善；提高"],"en":["to make or become better"]}', NULL, 'improve performance/quality/efficiency', '[{"en":"The company needs to improve customer service.","zh-TW":"公司需要改善客戶服務。"},{"en":"His English has improved significantly.","zh-TW":"他的英語有了顯著的進步。"}]', '{"noun":"improvement","verb":"improve","adjective":"improved"}', NULL, 3, 1628, NULL),
(1629, 'improvement', 'ɪmˈpruːvmənt', 'noun', '{"zh-TW":["改善；進步","提高"],"en":["a positive change","progress made"]}', NULL, 'significant improvement/room for improvement', '[{"en":"There is room for improvement in our process.","zh-TW":"我們的流程有改善的空間。"}]', '{"verb":"improve","adjective":"improved","adverb":"improved"}', NULL, 4, 1629, 134),
(1630, 'impulse', '/ˈɪmpʌls/', 'noun', '{"zh-TW":["衝動；推動力"],"en":["a sudden strong urge; a driving force"]}', NULL, 'impulse buying / on impulse / impulse purchase', '[{"en":"Impulse buying accounts for 30% of retail sales.","zh-TW":"衝動購買佔零售銷售額的30%。"},{"en":"She bought the dress on impulse.","zh-TW":"她一時衝動買了那件洋裝。"}]', '{"noun":"impulse","adjective":"impulsive","adverb":"impulsively"}', NULL, 3, 1630, NULL),
(1631, 'in-box', '/ˈɪnbɒks/', 'noun', '{"zh-TW":["收件匣；待辦文件匣"],"en":["a container for incoming mail or tasks"]}', NULL, 'clear your in-box / full in-box', '[{"en":"She cleared her in-box before starting the new project.","zh-TW":"她在開始新項目之前清空了收件匣。"},{"en":"His in-box was overflowing with unread emails.","zh-TW":"他的收件匣裝滿了未讀電子郵件。"}]', NULL, NULL, 2, 1631, NULL),
(1632, 'in-depth', 'ɪn dɛpθ', 'adjective', '{"zh-TW":["深入的；徹底的","詳細的"],"en":["thorough and detailed","comprehensive"]}', NULL, 'in-depth analysis/in-depth review', '[{"en":"Please conduct an in-depth analysis.","zh-TW":"請進行深入分析。"}]', '{"adverb":"in depth"}', NULL, 3, 1632, NULL),
(1633, 'in-house', '/ˌɪn ˈhaʊs/', 'adjective', '{"zh-TW":["內部的；公司自有的"],"en":["done or produced within an organization rather than outsourced"]}', NULL, 'in-house team / in-house production / keep in-house', '[{"en":"The company decided to handle legal work in-house rather than outsourcing.","zh-TW":"公司決定在內部處理法律工作而不是外包。"},{"en":"In-house manufacturing gives greater quality control.","zh-TW":"內部製造提供了更大的品質控制。"}]', NULL, NULL, 3, 1633, NULL),
(1634, 'in-network', '/ɪn ˈnɛtwɜːrk/', 'adjective', '{"zh-TW":["網絡內；保險體系內"],"en":["within the group of healthcare providers covered by an insurance plan"]}', NULL, 'in-network provider / in-network hospital', '[{"en":"Using an in-network doctor reduces your costs.","zh-TW":"使用網絡內的醫生可降低您的費用。"},{"en":"Check if the specialist is in-network before making an appointment.","zh-TW":"預約前請確認該專科醫生是否在網絡內。"}]', NULL, NULL, 4, 1634, NULL),
(1635, 'inadequate', '/ɪnˈædɪkwət/', 'adjective', '{"zh-TW":["不足的；不充分的"],"en":["not enough or not good enough"]}', NULL, 'inadequate funding/resources/training', '[{"en":"The budget is inadequate for the project''s needs.","zh-TW":"預算不足以滿足項目需求。"},{"en":"Inadequate training led to the error.","zh-TW":"培訓不足導致了錯誤。"}]', '{"noun":"inadequacy","adjective":"inadequate","adverb":"inadequately"}', NULL, 4, 1635, NULL),
(1636, 'incentive', '/ɪnˈsentɪv/', 'noun', '{"zh-TW":["激勵；獎勵；動機"],"en":["something that encourages a person to do something"]}', NULL, 'financial/tax incentive / provide an incentive', '[{"en":"The company offers incentives to attract new employees.","zh-TW":"公司提供激勵措施來吸引新員工。"},{"en":"Tax incentives encourage business investment.","zh-TW":"稅收優惠鼓勵企業投資。"}]', '{"noun":"incentive","verb":"incentivize"}', NULL, 3, 1636, 135),
(1637, 'incentivize', '/ɪnˈsentɪvaɪz/', 'verb', '{"zh-TW":["激勵；提供獎勵"],"en":["to provide incentives to encourage action"]}', NULL, 'incentivize employees/performance', '[{"en":"The program incentivizes employees to meet targets.","zh-TW":"該計劃激勵員工達成目標。"},{"en":"Tax breaks incentivize green energy investment.","zh-TW":"稅收優惠激勵綠色能源投資。"}]', '{"noun":"incentive","verb":"incentivize"}', NULL, 4, 1637, 692),
(1638, 'inception', '/ɪnˈsepʃən/', 'noun', '{"zh-TW":["開始；創立"],"en":["the start or establishment of an organization or project"]}', NULL, 'since inception / date of inception / from inception to completion', '[{"en":"The company has grown steadily since its inception in 2010.","zh-TW":"公司自2010年創立以來一直穩定增長。"},{"en":"The project was completed ahead of schedule from inception.","zh-TW":"項目從一開始就提前完成了。"}]', '{"verb":"incept"}', NULL, 3, 1638, NULL),
(1639, 'incidence', '/ˈɪnsɪdəns/', 'noun', '{"zh-TW":["發生率"],"en":["the rate at which something occurs"]}', NULL, 'high/low incidence of', '[{"en":"There is a high incidence of diabetes in this region.","zh-TW":"該地區糖尿病發生率很高。"},{"en":"The incidence of workplace injuries has decreased.","zh-TW":"工傷事故發生率已經下降。"}]', '{"noun":"incidence, incident","adjective":"incidental"}', NULL, 3, 1639, NULL),
(1640, 'incident', '/ˈɪnsɪdənt/', 'noun', '{"zh-TW":["事件；事故"],"en":["an event, especially one that is unusual or unpleasant"]}', NULL, 'report an incident / security incident', '[{"en":"The incident was reported to the police.","zh-TW":"該事件已報告給警方。"},{"en":"Several minor incidents occurred during the event.","zh-TW":"活動期間發生了幾起小事故。"}]', '{"noun":"incident, incidence","adjective":"incidental","adverb":"incidentally"}', NULL, 3, 1640, NULL),
(1641, 'incline', '/ɪnˈklaɪn/', 'verb', '{"zh-TW":["傾向；使傾斜"],"en":["to tend toward; to lean"]}', NULL, 'inclined to agree / be inclined to', '[{"en":"I am inclined to accept the offer.","zh-TW":"我傾向於接受這個提議。"},{"en":"Management is inclined to approve the budget.","zh-TW":"管理層傾向於批准預算。"}]', '{"noun":"inclination","verb":"incline","adjective":"inclined"}', NULL, 3, 1641, NULL),
