(1643, 'inclusion', '/ɪnˈkluːʒən/', 'noun', '{"zh-TW":["包容性；納入"],"en":["creating an environment where everyone feels valued and respected"]}', NULL, 'diversity and inclusion / foster inclusion / inclusion policy', '[{"en":"Inclusion initiatives made employees feel more valued.","zh-TW":"包容性倡議使員工感到更受重視。"},{"en":"The company scored highly on inclusion in its employee survey.","zh-TW":"公司在員工調查的包容性指標上得分很高。"}]', '{"adjective":"inclusive","verb":"include"}', NULL, 3, 1643, NULL),
