(1645, 'inconvenience', '/ˌɪnkənˈviːniəns/', 'noun, verb', '{"zh-TW":["不便；麻煩"],"en":["trouble or difficulty caused to someone"]}', NULL, 'cause/apologize for the inconvenience', '[{"en":"We apologize for any inconvenience caused.","zh-TW":"對造成的任何不便，我們深表歉意。"},{"en":"The construction work may inconvenience residents.","zh-TW":"施工可能會給居民帶來不便。"}]', '{"noun":"inconvenience","adjective":"inconvenient","verb":"inconvenience"}', NULL, 5, 1645, NULL),
(1646, 'incorporate', '/ɪnˈkɔːrpəreɪt/', 'verb', '{"zh-TW":["納入；合併","成立公司"],"en":["to include as part of something","to form a legal corporation"]}', NULL, 'incorporate feedback/changes/features', '[{"en":"We incorporated customer feedback into the new design.","zh-TW":"我們將客戶反饋納入新設計中。"},{"en":"The business was incorporated in 2020.","zh-TW":"這家企業於2020年註冊成立。"}]', '{"noun":"incorporation","verb":"incorporate","adjective":"incorporated"}', NULL, 4, 1646, 369),
(1647, 'incoterms', '/ˈɪnkəʊtɜːrmz/', 'noun', '{"zh-TW":["國際貿易術語"],"en":["internationally recognized trade terms defining responsibilities"]}', NULL, 'specify incoterms / FOB incoterms', '[{"en":"The contract specified CIF incoterms for this shipment.","zh-TW":"合約規定了本次貨運使用CIF國際貿易術語。"},{"en":"Understanding incoterms prevents disputes over shipping costs.","zh-TW":"了解國際貿易術語可防止運費方面的爭議。"}]', NULL, NULL, 3, 1647, NULL),
(1648, 'increase', '/ɪnˈkriːs/', 'verb, noun', '{"zh-TW":["增加；提高"],"en":["to become or make greater in amount"]}', NULL, 'increase in sales/demand / a significant increase', '[{"en":"Sales increased by 20% last quarter.","zh-TW":"上季度銷售額增長了20%。"},{"en":"There has been a steady increase in demand.","zh-TW":"需求持續穩定增長。"}]', '{"noun":"increase","verb":"increase","adjective":"increasing","adverb":"increasingly"}', NULL, 3, 1648, 136),
(1649, 'incremental', '/ˌɪŋkrəˈmentəl/', 'adjective', '{"zh-TW":["漸進的；逐步的"],"en":["made in small progressive steps rather than all at once"]}', NULL, 'incremental improvement / incremental cost / incremental change', '[{"en":"The company adopted incremental improvements rather than major overhaul.","zh-TW":"公司採用了漸進式改進而非重大改革。"},{"en":"Incremental cost increases are easier to absorb than sudden rises.","zh-TW":"漸進式成本增加比突然上漲更容易消化。"}]', '{"adverb":"incrementally","noun":"increment"}', NULL, 4, 1649, 883);
