(1654, 'indemnification', '/ɪnˌdɛmnɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["賠償；保障"],"en":["the action of compensating for loss or damage"]}', NULL, 'indemnification clause / seek indemnification', '[{"en":"The contract includes an indemnification clause for third-party claims.","zh-TW":"合約包含第三方索賠的賠償條款。"},{"en":"The company agreed to indemnification for any losses incurred.","zh-TW":"公司同意對所發生的任何損失進行賠償。"}]', '{"verb":"indemnify","noun":"indemnity"}', NULL, 5, 1654, 794),
(1655, 'indemnify', '/ɪnˈdɛmnɪfaɪ/', 'verb', '{"zh-TW":["賠償；保障免於損失"],"en":["to compensate for harm or loss; to protect from liability"]}', NULL, 'agree to indemnify / indemnify against loss', '[{"en":"The supplier agreed to indemnify the buyer against defective products.","zh-TW":"供應商同意就有問題的產品對買方進行賠償。"},{"en":"The contract includes a clause to indemnify both parties.","zh-TW":"合約包含保障雙方免於損失的條款。"}]', '{"noun":"indemnification","noun2":"indemnity"}', NULL, 3, 1655, NULL),
(1656, 'indemnity', '/ɪnˈdemnɪti/', 'noun', '{"zh-TW":["賠償；免責"],"en":["security against loss or damage; compensation for harm suffered"]}', NULL, 'indemnity clause / indemnity agreement / hold harmless indemnity', '[{"en":"The contract includes an indemnity clause protecting the client.","zh-TW":"合約包含保護客戶的賠償條款。"},{"en":"The insurance policy provides indemnity against business interruption.","zh-TW":"保險單提供針對業務中斷的賠償。"}]', '{"verb":"indemnify","adjective":"indemnified"}', NULL, 3, 1656, NULL),
