(1667, 'inefficiency', '/ˌɪnɪˈfɪʃənsi/', 'noun', '{"zh-TW":["低效率；低效"],"en":["failure to make best use of time, money, or resources"]}', NULL, 'address inefficiencies / operational inefficiency', '[{"en":"The audit identified several inefficiencies in the procurement process.","zh-TW":"審計識別了採購流程中的幾個低效問題。"},{"en":"Inefficiency in logistics increased delivery costs significantly.","zh-TW":"物流低效顯著增加了配送成本。"}]', '{"adjective":"inefficient","adverb":"inefficiently"}', NULL, 4, 1667, NULL),
(1668, 'inevitable', '/ɪnˈevɪtəbl/', 'adjective', '{"zh-TW":["不可避免的"],"en":["certain to happen; unavoidable"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"evit","meaning":"avoid (避免)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"不能避免的。"}', 'inevitable result / inevitable change; inevitable consequence/result/outcome', '[{"en":"Change is inevitable in any organization.","zh-TW":"在任何組織中，變革都是不可避免的。"},{"en":"Delays were inevitable given the weather.","zh-TW":"考慮到天氣，延遲是不可避免的。"},{"en":"Change is inevitable in any organization.","zh-TW":"變革在任何組織中都是不可避免的。"},{"en":"It was inevitable that prices would rise.","zh-TW":"價格上漲是不可避免的。"}]', '{"adverb":"inevitably","noun":"inevitability","adjective":"inevitable"}', NULL, 4, 1668, NULL),
(1669, 'infer', '/ɪnˈfɜːr/', 'verb', '{"zh-TW":["推斷；推論"],"en":["to conclude from evidence and reasoning"]}', NULL, 'infer from / can be inferred', '[{"en":"We can infer from the data that sales are declining.","zh-TW":"我們可以從數據推斷出銷售額正在下降。"},{"en":"What can be inferred from this chart?","zh-TW":"從這張圖表中可以推斷出什麼？"}]', '{"noun":"inference","verb":"infer"}', NULL, 2, 1669, NULL),
