(1671, 'inflation', '/ɪnˈfleɪʃn/', 'noun', '{"zh-TW":["通貨膨脹"],"en":["a general increase in prices over time"]}', NULL, 'inflation rate / fight/curb inflation / rising inflation', '[{"en":"The inflation rate reached 8% this year.","zh-TW":"今年通貨膨脹率達到8%。"},{"en":"The central bank raised interest rates to combat inflation.","zh-TW":"央行提高利率以對抗通脹。"}]', '{"noun":"inflation","verb":"inflate","adjective":"inflationary"}', NULL, 3, 1671, NULL),
