(1674, 'influence', '/ˈɪnfluəns/', 'noun', '{"zh-TW":["影響","影響；影響力"],"en":["the capacity to have an effect on someone or something","the power to affect someone or something"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"flu","meaning":"flow (流)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"流入其中產生作用，即「影響」。"}', 'have influence / under the influence of / positive influence; have influence on / under the influence of', '[{"en":"Social media has a huge influence on young people.","zh-TW":"社群媒體對年輕人有巨大的影響。"},{"en":"She used her influence to get the job.","zh-TW":"她利用自己的影響力得到了這份工作。"},{"en":"Social media has a huge influence on consumer behavior.","zh-TW":"社群媒體對消費者行為有巨大影響。"},{"en":"His research influenced the field significantly.","zh-TW":"他的研究對該領域產生了重大影響。"}]', '{"verb":"influence","adjective":"influential","noun":"influence"}', NULL, 3, 1674, NULL),
