(1682, 'inhibit', '/ɪnˈhɪbɪt/', 'verb', '{"zh-TW":["抑制；阻止"],"en":["to prevent or slow down a process"]}', NULL, 'inhibit growth/development/creativity', '[{"en":"Fear of failure can inhibit creativity.","zh-TW":"對失敗的恐懼會抑制創造力。"},{"en":"The drug inhibits the growth of cancer cells.","zh-TW":"這種藥物抑制癌細胞的生長。"}]', '{"noun":"inhibition, inhibitor","verb":"inhibit"}', NULL, 3, 1682, NULL),
