(1684, 'initiate', '/ɪˈnɪʃieɪt/', 'verb', '{"zh-TW":["發起；開始"],"en":["to cause a process or action to begin"]}', NULL, 'initiate a project/discussion/process', '[{"en":"The manager initiated a review of company policies.","zh-TW":"經理發起了公司政策的審查。"},{"en":"Who initiated the negotiations?","zh-TW":"是誰發起了談判？"}]', '{"noun":"initiation, initiative, initiator","verb":"initiate","adjective":"initial"}', NULL, 3, 1684, 694),
(1685, 'initiative', '/ɪˈnɪʃətɪv/', 'noun', '{"zh-TW":["主動性；倡議","主動性；倡議；計劃"],"en":["the ability to act independently","a new plan or program","the ability to act independently; a new plan to deal with a problem"]}', '{"prefix":{"text":"in-","meaning":"into (進入)"},"root":{"text":"it","meaning":"go (走)"},"suffix":{"text":"-iative","meaning":"relating to (相關的)"},"logic":"走進去開始行動的，即「主動性」。"}', 'take the initiative / new initiative / on one''s own initiative; take the initiative / a government initiative', '[{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這場活動。"},{"en":"The government launched a new environmental initiative.","zh-TW":"政府推出了新的環保倡議。"},{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這次活動。"},{"en":"The company launched a new green initiative.","zh-TW":"公司發起了一項新的綠色倡議。"}]', '{"noun":"initiative, initiation","verb":"initiate"}', NULL, 4, 1685, 139),
(1686, 'injunction', '/ɪnˈdʒʌŋkʃən/', 'noun', '{"zh-TW":["禁令；法院強制令"],"en":["a court order requiring someone to do or stop doing something"]}', NULL, 'seek an injunction / court injunction', '[{"en":"The court granted an injunction preventing the company from publishing.","zh-TW":"法院頒布了禁止該公司出版的禁令。"},{"en":"A temporary injunction was issued pending the full hearing.","zh-TW":"在全面聆訊前，法院發出了臨時禁令。"}]', NULL, NULL, 4, 1686, NULL),
(1687, 'inn', '/ɪn/', 'noun', '{"zh-TW":["旅館；客棧"],"en":["a small hotel, especially in the countryside"]}', NULL, 'country inn / village inn', '[{"en":"They stayed at a cozy country inn for the weekend.","zh-TW":"他們在週末住在一家舒適的鄉村旅館。"},{"en":"The inn has only twelve rooms and offers home-cooked meals.","zh-TW":"這家客棔只有十二間客房，提供家常菜餚。"}]', NULL, NULL, 1, 1687, NULL),
(1688, 'innovation', '/ˌɪnəˈveɪʃn/', 'noun', '{"zh-TW":["創新","創新；革新"],"en":["a new method, idea, or product"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"引入新事物的過程，即「創新」。"}', 'drive innovation / technological innovation; technological/product innovation / drive innovation', '[{"en":"Innovation is key to staying competitive.","zh-TW":"創新是保持競爭力的關鍵。"},{"en":"The company is known for its technological innovations.","zh-TW":"這家公司以技術創新聞名。"},{"en":"The company is known for its innovation in design.","zh-TW":"該公司以設計創新聞名。"}]', '{"verb":"innovate","adjective":"innovative","noun2":"innovator","noun":"innovation, innovator"}', NULL, 4, 1688, 580),
(1689, 'innovative', '/ˈɪnəveɪtɪv/', 'adjective', '{"zh-TW":["創新的"],"en":["featuring new methods or ideas"]}', NULL, 'innovative approach/solution/technology', '[{"en":"The company is known for its innovative products.","zh-TW":"該公司以其創新產品聞名。"},{"en":"We need innovative solutions to complex problems.","zh-TW":"我們需要創新的解決方案來應對複雜問題。"}]', '{"noun":"innovation, innovator","adjective":"innovative","verb":"innovate"}', NULL, 4, 1689, 885),
(1690, 'inpatient', '/ˈɪnpeɪʃənt/', 'noun', '{"zh-TW":["住院病患"],"en":["a patient who stays in a hospital for treatment"]}', NULL, 'inpatient care / inpatient treatment', '[{"en":"Inpatient care is required for serious surgeries.","zh-TW":"重大手術需要住院護理。"},{"en":"The hospital has 200 inpatient beds.","zh-TW":"這家醫院有200張住院病床。"}]', '{"adjective":"inpatient"}', NULL, 3, 1690, NULL),
(1691, 'input', '/ˈɪnpʊt/', 'noun, verb', '{"zh-TW":["投入；輸入","提供意見"],"en":["what is put in; contribution","to enter data"]}', NULL, 'provide input / input data', '[{"en":"We value your input on this project.","zh-TW":"我們重視您對這個項目的意見。"},{"en":"Please input your password to continue.","zh-TW":"請輸入您的密碼以繼續。"}]', '{"noun":"input","verb":"input"}', NULL, 2, 1691, 372),
(1692, 'inquire', '/ɪnˈkwaɪər/', 'verb', '{"zh-TW":["詢問；調查"],"en":["to ask for information"]}', NULL, 'inquire about / inquire into', '[{"en":"She called to inquire about the job opening.","zh-TW":"她打電話詢問職位空缺的事。"},{"en":"The committee will inquire into the matter.","zh-TW":"委員會將對此事進行調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 1692, NULL),
(1693, 'inquiry', '/ɪnˈkwaɪəri/', 'noun', '{"zh-TW":["詢問；調查"],"en":["a request for information; an official investigation"]}', NULL, 'make an inquiry / customer inquiry / public inquiry', '[{"en":"We received several inquiries about the new product.","zh-TW":"我們收到了幾份關於新產品的詢問。"},{"en":"A public inquiry was launched into the incident.","zh-TW":"對該事件展開了公開調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 1693, 35),
(1694, 'insert', '/ɪnˈsɜːrt/', 'verb, noun', '{"zh-TW":["插入；嵌入","插入物"],"en":["to put something inside something else","something inserted"]}', NULL, 'insert a clause/coin/key', '[{"en":"Please insert your card into the machine.","zh-TW":"請將卡片插入機器。"},{"en":"A new clause was inserted into the contract.","zh-TW":"合同中插入了一項新條款。"}]', '{"noun":"insert, insertion","verb":"insert"}', NULL, 2, 1694, NULL),
(1695, 'inside', '/ɪnˈsaɪd/', 'preposition', '{"zh-TW":["在…裡面"],"en":["in or into the interior of"]}', NULL, 'inside information / inside out', '[{"en":"He has inside knowledge of the deal.","zh-TW":"他有這筆交易的內部消息。"},{"en":"She knows the business inside out.","zh-TW":"她對這個業務瞭若指掌。"}]', '{"preposition":"inside","noun":"inside","noun2":"insider","adjective":"inside"}', NULL, 2, 1695, NULL),
(1696, 'insight', '/ˈɪnsaɪt/', 'noun', '{"zh-TW":["洞察力；見解"],"en":["a deep understanding of something"]}', NULL, 'gain/provide insight into', '[{"en":"The report provides valuable insights into consumer behavior.","zh-TW":"該報告提供了關於消費者行為的寶貴見解。"},{"en":"She has keen insight into human nature.","zh-TW":"她對人性有敏銳的洞察力。"}]', '{"noun":"insight","adjective":"insightful"}', NULL, 3, 1696, NULL),
(1697, 'insist', '/ɪnˈsɪst/', 'verb', '{"zh-TW":["堅持；堅決要求"],"en":["to demand something firmly"]}', NULL, 'insist on / insist that', '[{"en":"The client insisted on a full refund.","zh-TW":"客戶堅持要求全額退款。"},{"en":"We insist that all safety protocols be followed.","zh-TW":"我們堅持必須遵守所有安全規程。"}]', '{"noun":"insistence","verb":"insist","adjective":"insistent"}', NULL, 2, 1697, NULL),
(1698, 'insolvency', '/ɪnˈsɒlvənsi/', 'noun', '{"zh-TW":["破產；無力償債"],"en":["the state of being unable to pay debts"]}', NULL, 'risk of insolvency / declare insolvency', '[{"en":"The firm is at risk of insolvency.","zh-TW":"該公司面臨破產風險。"},{"en":"They filed for insolvency last quarter.","zh-TW":"他們上一季申請了破產。"}]', '{"noun":"insolvency","adjective":"insolvent"}', NULL, 4, 1698, NULL),
(1699, 'insolvent', '/ɪnˈsɒlvənt/', 'adjective', '{"zh-TW":["資不抵債的；破產的"],"en":["unable to pay debts when they fall due"]}', NULL, 'declared insolvent / technically insolvent', '[{"en":"The company was declared insolvent after missing three payments.","zh-TW":"公司在錯過三次還款後被宣告資不抵債。"},{"en":"Insolvent businesses can apply for protection under insolvency law.","zh-TW":"資不抵債的企業可以根據破產法申請保護。"}]', '{"noun":"insolvency"}', NULL, 3, 1699, NULL);
