(1700, 'insourcing', '/ˈɪnsɔːrsɪŋ/', 'noun', '{"zh-TW":["內包；回歸自辦"],"en":["bringing previously outsourced work back in-house"]}', NULL, 'insourcing decision / insourcing strategy', '[{"en":"Insourcing IT services gave the firm better control.","zh-TW":"將IT服務內包讓公司擁有更好的控制。"},{"en":"The trend toward insourcing reflects quality concerns.","zh-TW":"內包趨勢反映出對品質的關注。"}]', '{"verb":"insource"}', NULL, 4, 1700, NULL),
