(1702, 'inspection', '/ɪnˈspekʃn/', 'noun', '{"zh-TW":["檢查；視察"],"en":["a careful examination of something"]}', NULL, 'safety/quality inspection / pass inspection', '[{"en":"The factory passed its annual safety inspection.","zh-TW":"工廠通過了年度安全檢查。"},{"en":"Regular inspections ensure product quality.","zh-TW":"定期檢查確保產品品質。"}]', '{"noun":"inspection, inspector","verb":"inspect"}', NULL, 4, 1702, 581),
(1703, 'install', '/ɪnˈstɔːl/', 'verb', '{"zh-TW":["安裝；設置"],"en":["to put equipment or software in place for use"]}', NULL, 'install software/equipment/a system', '[{"en":"We need to install the new software by Friday.","zh-TW":"我們需要在週五前安裝新軟體。"},{"en":"Solar panels were installed on the roof.","zh-TW":"太陽能板被安裝在屋頂上。"}]', '{"noun":"installation, installment","verb":"install"}', NULL, 3, 1703, NULL),
(1704, 'installment', '/ɪnˈstɔːlmənt/', 'noun', '{"zh-TW":["分期付款"],"en":["one of several payments made over a period of time"]}', NULL, 'pay in installments / monthly installment', '[{"en":"You can pay for the equipment in monthly installments.","zh-TW":"你可以按月分期付款購買設備。"},{"en":"The first installment is due next week.","zh-TW":"第一期款項下週到期。"}]', '{"noun":"installment, installation","verb":"install"}', NULL, 4, 1704, NULL),
(1705, 'instalment', '/ɪnˈstɔːlmənt/', 'noun', '{"zh-TW":["分期付款額"],"en":["one of several regular payments made to settle a debt"]}', NULL, 'pay in instalments / instalment plan', '[{"en":"The equipment was purchased with a 24-month instalment plan.","zh-TW":"設備以24個月的分期付款計劃購買。"},{"en":"Monthly instalments make high-cost purchases more affordable.","zh-TW":"每月分期付款使高成本採購更加負擔得起。"}]', '{"verb":"install","synonym":"installment"}', NULL, 4, 1705, NULL),
(1706, 'instance', '/ˈɪnstəns/', 'noun', '{"zh-TW":["實例；情況"],"en":["an example or case of something"]}', NULL, 'for instance / in this instance', '[{"en":"There have been several instances of fraud.","zh-TW":"已經發生了幾起詐騙事件。"},{"en":"For instance, many companies now allow remote work.","zh-TW":"例如，許多公司現在允許遠端工作。"}]', '{"noun":"instance"}', NULL, 3, 1706, NULL),
(1707, 'instead', '/ɪnˈstɛd/', 'adverb', '{"zh-TW":["代替；反而"],"en":["as an alternative"]}', NULL, 'instead of / use instead', '[{"en":"Let''s use email instead of fax.","zh-TW":"我們用電子郵件代替傳真吧。"},{"en":"Instead, we should focus on quality.","zh-TW":"相反地，我們應該著重品質。"}]', '{"adverb":"instead"}', NULL, 3, 1707, NULL),
(1708, 'institute', '/ˈɪnstɪtuːt/', 'noun, verb', '{"zh-TW":["機構；研究所","制定；開始"],"en":["an organization for education or research","to introduce or establish"]}', NULL, 'research institute / institute changes/reforms', '[{"en":"She works at a research institute.","zh-TW":"她在一家研究機構工作。"},{"en":"The company instituted new security measures.","zh-TW":"公司制定了新的安全措施。"}]', '{"noun":"institute, institution","verb":"institute","adjective":"institutional"}', NULL, 3, 1708, NULL),
(1709, 'institution', '/ˌɪnstɪˈtuːʃn/', 'noun', '{"zh-TW":["機構；制度"],"en":["a large organization; an established system"]}', NULL, 'financial/educational institution', '[{"en":"Banks are important financial institutions.","zh-TW":"銀行是重要的金融機構。"},{"en":"Marriage is a social institution.","zh-TW":"婚姻是一種社會制度。"}]', '{"noun":"institution","adjective":"institutional","verb":"institutionalize"}', NULL, 4, 1709, NULL),
(1710, 'instruct', '/ɪnˈstrʌkt/', 'verb', '{"zh-TW":["指示；教導"],"en":["to direct or teach someone to do something"]}', NULL, 'instruct employees / instruct on procedure', '[{"en":"Please instruct the team on the new process.","zh-TW":"請指示團隊新的流程。"},{"en":"She instructed the interns on office procedures.","zh-TW":"她指導實習生了解辦公室程序。"}]', '{"noun":"instruction","noun2":"instructor","adjective":"instructed"}', NULL, 3, 1710, NULL),
(1711, 'instruction', '/ɪnˈstrʌkʃn/', 'noun', '{"zh-TW":["指示；說明；教學"],"en":["directions or orders; teaching"]}', NULL, 'follow instructions / give instructions', '[{"en":"Please read the instructions carefully before use.","zh-TW":"使用前請仔細閱讀說明。"},{"en":"He gave clear instructions to his team.","zh-TW":"他向團隊下達了明確的指示。"}]', '{"noun":"instruction, instructor","verb":"instruct","adjective":"instructive"}', NULL, 4, 1711, NULL),
(1712, 'instructor', '/ɪnˈstrʌktər/', 'noun', '{"zh-TW":["講師；教練"],"en":["a person who teaches"]}', NULL, 'driving instructor / fitness instructor', '[{"en":"The instructor explained the exercise.","zh-TW":"教練解釋了這個練習。"},{"en":"She works as a yoga instructor.","zh-TW":"她是一名瑜伽教練。"}]', '{"verb":"instruct","noun2":"instruction"}', NULL, 4, 1712, NULL),
(1713, 'instrument', '/ˈɪnstrəmənt/', 'noun', '{"zh-TW":["儀器；工具；樂器"],"en":["a tool or device; a means to achieve something"]}', NULL, 'financial instrument / measuring instrument', '[{"en":"The laboratory is equipped with precision instruments.","zh-TW":"實驗室配備了精密儀器。"},{"en":"Bonds are common financial instruments.","zh-TW":"債券是常見的金融工具。"}]', '{"noun":"instrument, instrumentation","adjective":"instrumental"}', NULL, 4, 1713, NULL),
(1714, 'insurance', '/ɪnˈʃʊrəns/', 'noun', '{"zh-TW":["保險"],"en":["an arrangement for compensation of loss or damage"]}', NULL, 'health/life/car insurance / insurance policy', '[{"en":"All employees receive health insurance benefits.","zh-TW":"所有員工都享有健康保險福利。"},{"en":"You should take out travel insurance.","zh-TW":"你應該購買旅行保險。"}]', '{"noun":"insurance, insurer","verb":"insure","adjective":"insured"}', NULL, 3, 1714, NULL),
(1715, 'intangible', '/ɪnˈtændʒɪbəl/', 'adjective', '{"zh-TW":["無形的；難以量化的"],"en":["not physical; not easily defined or measured"]}', NULL, 'intangible benefits / intangible value / intangible skills', '[{"en":"Brand reputation is an intangible asset with significant value.","zh-TW":"品牌聲譽是一項具有重大價值的無形資產。"},{"en":"The merger created intangible benefits such as knowledge sharing.","zh-TW":"合併創造了知識共享等無形利益。"}]', '{"opposite":"tangible","noun":"intangible"}', NULL, 4, 1715, NULL),
(1716, 'integral', '/ˈɪntɪɡrəl/', 'adjective', '{"zh-TW":["不可或缺的；完整的"],"en":["essential; necessary for completeness"]}', NULL, 'integral part/component of', '[{"en":"Technology is an integral part of modern business.","zh-TW":"技術是現代商業不可或缺的一部分。"},{"en":"Teamwork is integral to our success.","zh-TW":"團隊合作對我們的成功至關重要。"}]', '{"noun":"integrity, integration","adjective":"integral","verb":"integrate"}', NULL, 3, 1716, NULL),
(1717, 'integrate', '/ˈɪntɪɡreɪt/', 'verb', '{"zh-TW":["整合；融合","整合；融入"],"en":["to combine into a whole","to combine things so they work together"]}', '{"prefix":{"text":"in-","meaning":"in (在內)"},"root":{"text":"tegr","meaning":"whole (完整)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使成為完整的一體，即「整合」。"}', 'integrate into / fully integrated; integrate into / integrate systems/data', '[{"en":"The new system integrates all departments.","zh-TW":"新系統整合了所有部門。"},{"en":"Immigrants gradually integrate into society.","zh-TW":"移民逐漸融入社會。"},{"en":"The new system integrates all departments into one platform.","zh-TW":"新系統將所有部門整合到一個平台上。"},{"en":"Immigrants often struggle to integrate into society.","zh-TW":"移民常常難以融入社會。"}]', '{"noun":"integration","adjective":"integrated","verb":"integrate"}', NULL, 3, 1717, 373),
(1718, 'integrated', 'ˈɪntɪɡreɪtɪd', 'adjective', '{"zh-TW":["集成的；整合的","一體化的"],"en":["combining parts into a whole","unified"]}', NULL, 'integrated system/integrated approach', '[{"en":"We use an integrated project management tool.","zh-TW":"我們使用集成的專案管理工具。"}]', '{"verb":"integrate","noun":"integration"}', NULL, 4, 1718, NULL),
(1719, 'integration', '/ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["整合；集成"],"en":["combining separate systems or software to work together"]}', NULL, 'system integration / API integration', '[{"en":"The integration of the new software took three weeks.","zh-TW":"新軟體的整合花了三週時間。"},{"en":"Seamless integration between platforms improves efficiency.","zh-TW":"平台之間的無縫整合提高了效率。"}]', '{"verb":"integrate","adjective":"integrated"}', NULL, 4, 1719, 582),
(1720, 'integrity', '/ɪnˈteɡrəti/', 'noun', '{"zh-TW":["正直；誠信","完整性"],"en":["the quality of being honest and morally upright","the state of being whole"]}', NULL, 'personal/professional integrity / data integrity', '[{"en":"He is known for his integrity and honesty.","zh-TW":"他以正直和誠實著稱。"},{"en":"We must ensure the integrity of the data.","zh-TW":"我們必須確保數據的完整性。"}]', '{"noun":"integrity","adjective":"integral"}', NULL, 3, 1720, NULL),
(1721, 'intellectual', '/ˌɪntəˈlektʃuəl/', 'adjective, noun', '{"zh-TW":["智力的；知識分子"],"en":["relating to the intellect; a person of high intelligence"]}', NULL, 'intellectual property / intellectual capital', '[{"en":"Intellectual property rights must be protected.","zh-TW":"知識產權必須受到保護。"},{"en":"The company invests heavily in intellectual capital.","zh-TW":"公司大力投資智力資本。"}]', '{"noun":"intellect, intellectual, intelligence","adjective":"intellectual","adverb":"intellectually"}', NULL, 4, 1721, NULL),
(1722, 'intelligence', '/ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["智力；情報"],"en":["the ability to learn; secret information"]}', NULL, 'artificial intelligence / business intelligence / market intelligence', '[{"en":"Artificial intelligence is transforming many industries.","zh-TW":"人工智慧正在改變許多行業。"},{"en":"Business intelligence tools help analyze data.","zh-TW":"商業智慧工具有助於分析數據。"}]', '{"noun":"intelligence","adjective":"intelligent","adverb":"intelligently"}', NULL, 4, 1722, NULL),
(1723, 'intend', '/ɪnˈtend/', 'verb', '{"zh-TW":["打算；意圖"],"en":["to plan or mean to do something"]}', NULL, 'intend to do / be intended for', '[{"en":"We intend to expand our operations next year.","zh-TW":"我們打算明年擴大營運。"},{"en":"This product is intended for professional use.","zh-TW":"此產品專供專業使用。"}]', '{"noun":"intention, intent","verb":"intend","adjective":"intentional, intended","adverb":"intentionally"}', NULL, 2, 1723, NULL),
